class Solution {
    public int[] twoSum(int[] numbers, int target) {
        int left = 0;
        int right = numbers.length - 1;

        while (left < right) {
            int sum = numbers[left] + numbers[right];
            if (sum == target) {
                return new int[]{left + 1, right + 1};
            }
            if (sum < target) {
                left++;
            } else {
                right--;
            }
        }

        return new int[]{-1, -1};
    }
}

class Solution {
    public int[] twoSum(int[] numbers, int target) {
        for (int i = 0; i < numbers.length; i++) {
            int complement = target - numbers[i];
            int index = binarySearch(numbers, i + 1, numbers.length - 1, complement);
            if (index != -1) {
                return new int[]{i + 1, index + 1};
            }
        }

        return new int[]{-1, -1};
    }

    private int binarySearch(int[] numbers, int left, int right, int target) {
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (numbers[mid] == target) {
                return mid;
            }
            if (numbers[mid] < target) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return -1;
    }
}

class Solution {
    public int[] twoSum(int[] numbers, int target) {
        int offset = 1000;
        int[] count = new int[2001];

        for (int number : numbers) {
            count[number + offset]++;
        }

        for (int firstValue = -1000; firstValue <= 1000; firstValue++) {
            int secondValue = target - firstValue;
            if (secondValue < -1000 || secondValue > 1000) {
                continue;
            }
            if (firstValue == secondValue) {
                if (count[firstValue + offset] >= 2) {
                    return findIndices(numbers, firstValue, secondValue);
                }
            } else if (count[firstValue + offset] > 0 && count[secondValue + offset] > 0) {
                return findIndices(numbers, firstValue, secondValue);
            }
        }

        return new int[]{-1, -1};
    }

    private int[] findIndices(int[] numbers, int firstValue, int secondValue) {
        int firstIndex = -1;
        int secondIndex = -1;
        for (int i = 0; i < numbers.length; i++) {
            if (numbers[i] == firstValue && firstIndex == -1) {
                firstIndex = i;
            } else if (numbers[i] == secondValue) {
                secondIndex = i;
                break;
            }
        }

        if (firstIndex > secondIndex) {
            int temp = firstIndex;
            firstIndex = secondIndex;
            secondIndex = temp;
        }
        return new int[]{firstIndex + 1, secondIndex + 1};
    }
}
